static int 
dtb_help_ed_help_text_create(
    DtbHelpEdHelpEditorInfo instance,
    Widget parent
)
{
    Arg	args[33];	/* need 28 args (add 5 to be safe) */
    int	n = 0;
    static DtbObjectHelpDataRec	help_data = {
        "",
        "",
        "",
    };
    char *tmp_txt;
    
    if (instance->help_text == NULL) {
        n = 0;
        XtSetArg(args[n], XmNbottomAttachment, XmATTACH_NONE);  ++n;
        XtSetArg(args[n], XmNrightOffset, 4);  ++n;
        XtSetArg(args[n], XmNrightAttachment, XmATTACH_FORM);  ++n;
        XtSetArg(args[n], XmNleftOffset, 10);  ++n;
        XtSetArg(args[n], XmNleftAttachment, XmATTACH_WIDGET);  ++n;
        XtSetArg(args[n], XmNtopOffset, 8);  ++n;
        XtSetArg(args[n], XmNtopAttachment, XmATTACH_FORM);  ++n;
        XtSetArg(args[n], XmNheight, 0);  ++n;
        XtSetArg(args[n], XmNwidth, 0);  ++n;
        XtSetArg(args[n], XmNscrollBarDisplayPolicy, XmAUTOMATIC);  ++n;
        XtSetArg(args[n], XmNvisualPolicy, XmVARIABLE);  ++n;
        XtSetArg(args[n], XmNscrollingPolicy, XmAPPLICATION_DEFINED);  ++n;
        XtSetArg(args[n], XmNy, 8);  ++n;
        XtSetArg(args[n], XmNx, 113);  ++n;
        XtSetArg(args[n], XmNwordWrap, True);  ++n;
        XtSetArg(args[n], XmNeditMode, XmMULTI_LINE_EDIT);  ++n;
        XtSetArg(args[n], XmNscrollHorizontal, False);  ++n;
        XtSetArg(args[n], XmNscrollVertical, True);  ++n;
        XtSetArg(args[n], XmNcolumns, 48);  ++n;
        XtSetArg(args[n], XmNrows, 6);  ++n;
        XtSetArg(args[n], XmNcursorPositionVisible, True);  ++n;
        XtSetArg(args[n], XmNeditable, True);  ++n;
        instance->help_text =
            XmCreateScrolledText(parent,
                "help_text", args, n);
        /*
         * Add help callback
         */
        tmp_txt = CATGETS(Dtb_project_catd, 8, 21, "Use this area to enter the text you'd like to appear as the context-sensitive help for the selected object.");
        help_data.help_text = XtMalloc(strlen(tmp_txt)+1);
        strcpy(help_data.help_text,tmp_txt);
        
        XtAddCallback(XtParent(instance->help_text),
            XmNhelpCallback, dtb_help_dispatch,
            (XtPointer)&help_data);
    }
    instance->help_text_scrolledwin = XtParent(instance->help_text);
    return 0;
}



